//! Integration tests for serving the dashboard under a base path
//! (`WEB_BASE_PATH` / `web::mount`) and for the default root behavior.
//!
//! Every redirect, form action, link and cookie path generated by the app
//! must carry the base prefix — the suite walks the real routers (web + API
//! merged, mounted at `/agent`) and checks each Location and Set-Cookie.
//!
//! First login for a privileged account now runs the mandatory TOTP
//! enrollment: `POST /login` sets an `mfa_pending` cookie and redirects to
//! `/mfa/enroll`, and only the enrolled code submission hands out the
//! `session` cookie. Tests that need a session walk that flow through
//! [`login_and_enroll`], which asserts base-path scoping on BOTH cookies.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use axum::body::Body;
use axum::http::{Request, StatusCode};
use http_body_util::BodyExt;
use sha2::{Digest, Sha256};
use telegram_agent::{api, config::Config, db::Db, util, web, web::WebState};
use tower::ServiceExt;

const BASE: &str = "/agent";

async fn make_state(base: &str) -> (WebState, tempfile::TempDir) {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let db = Db::new(db_path.to_str().unwrap()).unwrap();
    db.create_web_account("owner", "secret", "owner", None)
        .await
        .unwrap();
    db.set_config("setup_done", "1");
    let cfg = Config {
        bot_token: "0:dummy".to_string(),
        owner_id: 1,
        db_path: db_path.to_str().unwrap().to_string(),
        default_channel: None,
        crypto_token: None,
        ai_enabled: false,
        ai_provider: "openai".to_string(),
        ai_api_style: "openai".to_string(),
        ai_base_url: "https://api.openai.com/v1".to_string(),
        ai_api_key: None,
        ai_model: "gpt-4o-mini".to_string(),
        ai_daily_token_budget: None,
        mcp_owner_token: None,
    };
    let state = WebState {
        db: Arc::new(db),
        cfg,
        bot: teloxide::Bot::new("0:dummy"),
        login_attempts: Arc::new(Mutex::new(HashMap::new())),
        ai_test_inflight: Arc::new(tokio::sync::Mutex::new(())),
        base_path: base.to_string(),
    };
    (state, dir)
}

fn app_at(base: &str, state: WebState) -> axum::Router {
    web::mount(base, web::router(state.clone()).merge(api::router(state)))
}

async fn body_string(resp: axum::http::Response<Body>) -> String {
    let bytes = resp.into_body().collect().await.unwrap().to_bytes();
    String::from_utf8_lossy(&bytes).to_string()
}

fn location(resp: &axum::http::Response<Body>) -> String {
    resp.headers()
        .get("location")
        .unwrap()
        .to_str()
        .unwrap()
        .to_string()
}

fn set_cookie(resp: &axum::http::Response<Body>) -> String {
    resp.headers()
        .get("set-cookie")
        .unwrap()
        .to_str()
        .unwrap()
        .to_string()
}

/// Every Set-Cookie header value, in order (enrollment returns two: the
/// fresh session and the cleared pending cookie).
fn set_cookies(resp: &axum::http::Response<Body>) -> Vec<String> {
    resp.headers()
        .get_all("set-cookie")
        .iter()
        .filter_map(|v| v.to_str().ok().map(String::from))
        .collect()
}

/// The `name=value` pair from a Set-Cookie header value.
fn cookie_pair(set_cookie: &str) -> String {
    set_cookie.split(';').next().unwrap().to_string()
}

/// The full Set-Cookie header value whose cookie name is `name`.
fn named_cookie<'a>(cookies: &'a [String], name: &str) -> &'a str {
    let prefix = format!("{name}=");
    cookies
        .iter()
        .map(String::as_str)
        .find(|c| c.starts_with(&prefix))
        .unwrap_or_else(|| panic!("no {name} Set-Cookie among {cookies:?}"))
}

/// Mirrors the server's pending-MFA row key: sha256 hex of the raw
/// `mfa_pending` cookie token.
fn sha256_hex(s: &str) -> String {
    let mut h = Sha256::new();
    h.update(s.as_bytes());
    h.finalize().iter().map(|b| format!("{b:02x}")).collect()
}

/// Every Location observed across this suite must stay under the base path.
fn assert_prefixed(loc: &str) {
    assert!(
        loc.starts_with(BASE),
        "redirect escaped the base path: {loc:?}"
    );
}

/// Drives the mandatory first-login MFA enrollment for a privileged account
/// (owner/admin without TOTP) and returns the `session=<token>` cookie pair
/// for subsequent authenticated requests. Asserts the full contract on the
/// way:
///
/// 1. `POST {base}/login` -> 303 to `{base}/mfa/enroll` with a
///    `mfa_pending` cookie scoped to the base (`Path=/` at the root).
/// 2. `GET {base}/mfa/enroll` renders the QR svg and the code form with a
///    base-prefixed action.
/// 3. The TOTP secret is resolved exactly as the server resolves it: the
///    raw pending token hashes (sha256) to the pending-MFA row key. The
///    page shows the QR plus a copyable otpauth URI for manual entry, but
///    the test still resolves the secret server-side via the pending row
///    rather than parsing HTML.
/// 4. `POST {base}/mfa/enroll` with a valid 6-digit/30s TOTP code enables
///    MFA and answers 200 with two Set-Cookie headers — a base-scoped
///    `session` cookie and the `mfa_pending` cookie cleared (Max-Age=0) —
///    plus the "MFA enabled" page linking the dashboard.
async fn login_and_enroll(app: axum::Router, db: &Db, base: &str) -> String {
    // Mirrors WebState::cookie_path(): the base when mounted under one,
    // `/` when serving at the root. The trailing `;` in the Path assertions
    // pins the scope exactly (no accidental `Path=/agentfoo`).
    let cookie_path = if base.is_empty() { "/" } else { base };

    // 1. Login: pending cookie + redirect to enrollment (no session yet).
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{base}/login"))
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from("username=owner&password=secret"))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert!(
        loc.starts_with(base),
        "redirect escaped the base path: {loc:?}"
    );
    assert_eq!(loc, format!("{base}/mfa/enroll"));
    let pending = set_cookie(&resp);
    assert!(
        pending.starts_with("mfa_pending="),
        "first privileged login must set mfa_pending, not a session: {pending}"
    );
    assert!(
        pending.contains(&format!("Path={cookie_path};")),
        "mfa_pending cookie path not scoped to base: {pending}"
    );
    let pending_pair = cookie_pair(&pending);

    // 2. The enroll page renders the QR (the secret lives only in the QR
    //    modules) and the code form.
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("{base}/mfa/enroll"))
                .header("cookie", pending_pair.clone())
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
    let page = body_string(resp).await;
    assert!(
        page.contains(&format!("action=\"{base}/mfa/enroll\"")),
        "enroll form action missing base prefix:\n{page}"
    );
    assert!(
        page.contains("name=\"code\""),
        "enroll page lacks the code input:\n{page}"
    );
    assert!(
        page.contains("class=\"qr\"") && page.contains("<svg"),
        "enroll page must render the TOTP QR:\n{page}"
    );

    // 3. Resolve the pending secret (same lookup the server performs) and
    //    compute the current 6-digit / 30s TOTP code.
    let pending_token = pending_pair.strip_prefix("mfa_pending=").unwrap();
    let (_account_id, purpose, secret, _expires) = db
        .get_pending_mfa(&sha256_hex(pending_token))
        .expect("pending MFA row for the mfa_pending cookie");
    assert_eq!(purpose, "enroll");
    let secret = secret.unwrap_or_default();
    assert!(
        !secret.is_empty(),
        "enroll pending must carry the TOTP secret"
    );
    let code = util::totp_generate(
        &secret,
        chrono::Utc::now().timestamp() as u64,
        6usize,
        30u64,
    );
    assert_eq!(code.len(), 6, "TOTP code must be 6 digits: {code}");

    // 4. Enroll: the valid code swaps the pending cookie for a base-scoped
    //    session cookie on the "MFA enabled" page.
    let resp = app
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{base}/mfa/enroll"))
                .header("content-type", "application/x-www-form-urlencoded")
                .header("cookie", pending_pair)
                .body(Body::from(format!("code={code}")))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
    let cookies = set_cookies(&resp);
    let session = named_cookie(&cookies, "session").to_string();
    assert!(
        session.contains(&format!("Path={cookie_path};")),
        "session cookie path not scoped to base: {session}"
    );
    let cleared = named_cookie(&cookies, "mfa_pending");
    assert!(
        cleared.contains("Max-Age=0"),
        "enrollment must clear the mfa_pending cookie: {cleared}"
    );
    assert!(
        cleared.contains(&format!("Path={cookie_path};")),
        "clearing cookie path not scoped to base: {cleared}"
    );
    let body = body_string(resp).await;
    assert!(body.contains("MFA enabled"), "enrollment failed:\n{body}");
    assert!(
        body.contains(&format!("href=\"{base}/dashboard\"")),
        "enrollment page must link the dashboard:\n{body}"
    );
    session
}

#[tokio::test]
async fn login_page_urls_carry_base() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    let resp = app
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/login"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
    let body = body_string(resp).await;
    assert!(
        body.contains(&format!("action=\"{BASE}/login\"")),
        "login form action missing base prefix:\n{body}"
    );
    // The login page is the bare front-door shell (no nav pre-auth); the
    // base-prefixed URL contract now rides on the stylesheet link.
    assert!(
        body.contains(&format!("href=\"{BASE}/assets/app.css\"")),
        "stylesheet link missing base prefix:\n{body}"
    );
}

#[tokio::test]
async fn index_without_session_redirects_to_base_login() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    // Trailing-slash base root normalizes to the base, which then lands on
    // the login redirect: /agent/ -> /agent -> /agent/login.
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, BASE);

    let resp = app
        .oneshot(Request::builder().uri(BASE).body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/login"));
}

#[tokio::test]
async fn login_sets_scoped_cookie_and_dashboard_works() {
    let (state, _dir) = make_state(BASE).await;
    let db = state.db.clone();
    let app = app_at(BASE, state);

    // First privileged login no longer hands out a session directly: it sets
    // a base-scoped mfa_pending cookie, redirects to {BASE}/mfa/enroll, and
    // only the enrolled code submission yields the session. The full chain —
    // including base scoping of BOTH cookies — is asserted by the helper.
    let session = login_and_enroll(app.clone(), &db, BASE).await;
    assert!(session.starts_with("session="), "{session}");

    // With the session cookie the dashboard renders; without it redirects.
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/dashboard"))
                .header("cookie", session)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);

    let resp = app
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/dashboard"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/login"));
}

#[tokio::test]
async fn invalid_plan_redirects_to_base_plans() {
    let (state, _dir) = make_state(BASE).await;
    let db = state.db.clone();
    let app = app_at(BASE, state);
    // Session via the mandatory first-login MFA enrollment.
    let session = login_and_enroll(app.clone(), &db, BASE).await;

    let resp = app
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/plan"))
                .header("content-type", "application/x-www-form-urlencoded")
                .header("cookie", session)
                .body(Body::from(
                    "name=bronze&price=10&asset=TON&duration_days=notanumber",
                ))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/plans"));
}

#[tokio::test]
async fn logout_clears_scoped_cookie() {
    let (state, _dir) = make_state(BASE).await;
    let db = state.db.clone();
    let app = app_at(BASE, state);
    // A real session: first login enrolls MFA before handing out the cookie.
    let session = login_and_enroll(app.clone(), &db, BASE).await;

    let resp = app
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/logout"))
                .header("cookie", session)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/login"));
    let cleared = set_cookie(&resp);
    assert!(cleared.contains("Max-Age=0"), "{cleared}");
    assert!(
        cleared.contains(&format!("Path={BASE};")),
        "clearing cookie path not scoped to base: {cleared}"
    );
}

#[tokio::test]
async fn every_redirect_stays_under_base() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);

    // Logged-out walk over every redirecting GET route. "/" (the base root
    // with trailing slash) first normalizes to the base itself; the MFA
    // routes bounce to login when no mfa_pending cookie is present.
    for path in [
        "/",
        "/dashboard",
        "/settings",
        "/channels",
        "/plans",
        "/posts",
        "/logout",
        "/mfa/enroll",
        "/mfa/verify",
    ] {
        let resp = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("{BASE}{path}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert!(
            resp.status().is_redirection(),
            "{path} should redirect, got {}",
            resp.status()
        );
        let loc = location(&resp);
        assert_prefixed(&loc);
        let expected = if path == "/" {
            BASE.to_string()
        } else {
            format!("{BASE}/login")
        };
        assert_eq!(loc, expected, "{path} -> {loc}");
    }

    // And the login POST redirect: a privileged first login lands on MFA
    // enrollment, still under the base.
    let resp = app
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/login"))
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from("username=owner&password=secret"))
                .unwrap(),
        )
        .await
        .unwrap();
    assert!(resp.status().is_redirection());
    assert_prefixed(&location(&resp));
    assert_eq!(location(&resp), format!("{BASE}/mfa/enroll"));
}

#[tokio::test]
async fn settings_page_urls_carry_base() {
    let (state, _dir) = make_state(BASE).await;
    let db = state.db.clone();
    let (acc_id, _u, _h, _r, _s) = db.get_web_account_by_username("owner").unwrap();
    let token = db.create_web_session(acc_id, "owner", None, 7);
    let app = app_at(BASE, state);

    let resp = app
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/settings"))
                .header("cookie", format!("session={token}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
    let body = body_string(resp).await;
    assert!(
        body.contains(&format!("action=\"{BASE}/settings/save\"")),
        "settings save form action missing base prefix:\n{body}"
    );
    assert!(
        body.contains(&format!("action=\"{BASE}/settings/password\"")),
        "password form action missing base prefix:\n{body}"
    );
    assert!(
        body.contains(&format!("href=\"{BASE}/settings\"")),
        "rail foot Settings link missing base prefix:\n{body}"
    );
}

