#[tokio::test]
async fn api_login_under_base() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    let resp = app
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/api/v1/auth/login"))
                .header("content-type", "application/json")
                .body(Body::from(r#"{"username":"owner","password":"secret"}"#))
                .unwrap(),
        )
        .await
        .unwrap();
    // The owner account has no TOTP enrolled; REST login now mirrors the web
    // flow and requires console enrollment first (mfa_required), it must not
    // mint a token.
    assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
    let v: serde_json::Value = serde_json::from_str(&body_string(resp).await).unwrap();
    assert_eq!(v["error"]["code"], "mfa_required", "{v}");
}

#[tokio::test]
async fn default_mount_at_root() {
    let (state, _dir) = make_state("").await;
    let db = state.db.clone();
    let app = app_at("", state);

    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/login")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);

    // First login now enrolls MFA before any session exists; the helper
    // asserts both cookies it hands out (mfa_pending from the login POST,
    // session from the enrollment) are scoped to Path=/.
    let session = login_and_enroll(app.clone(), &db, "").await;
    assert!(session.starts_with("session="), "{session}");

    // Index without a session still redirects to /login.
    let resp = app
        .oneshot(Request::builder().uri("/").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    assert_eq!(location(&resp), "/login");
}
